"""Second question types for Mental Math (MM, UIL Number Sense). Every item is one quick question with a single exact
answer (mm-* answers are final automatically): the same trick run in reverse, on a neighbouring case, or as the
companion rule the chart pairs with it."""
from opl_dsl import Q

FILE, FRAMEWORK = "mm-second-types", "mental-math"
T = "Symbol('t')"


def M(name, skill, prompt, value, verify, explain, pace="recall", **kw):
    return Q(name, skill, prompt, value=value, verify=verify, explain=explain, pace=pace, final=True, tol=0.0001, **kw)


